def solve(payload):
    import math
    a, b, c = [payload[k] for k in ("a", "b", "c")]
    if a == 0:
        if b != 0:
            return {"kind": "roots", "roots": [-c/b]}
        return {"kind": "all" if c == 0 else "none", "roots": []}
    d = b*b-4*a*c
    if d < 0:
        return {"kind": "none", "roots": []}
    if d == 0:
        return {"kind": "roots", "roots": [-b/(2*a)]}
    q = -0.5*(b+math.copysign(math.sqrt(d), b))
    return {"kind": "roots", "roots": sorted([q/a, c/q])}

